29			}
30		}
31		for _, bad := range []string{"", "hooks.acme.example/x", "ftp://hooks.acme.example/", "https:///x", "https://unknown.example/x"} {
32			if err := e.Webhooks.CheckURL(ctx, bad); !errors.Is(err, webhooks.ErrInvalidURL) {
33				t.Errorf("CheckURL(%q) = %v, want ErrInvalidURL", bad, err)
34			}
