288	func TestWebhookEndpoints(t *testing.T) {
289		e := apitest.New(t)
290		var ep store.WebhookEndpoint
291		e.MustDo(http.StatusCreated, "POST", "/v1/webhook-endpoints", e.Acme.Key, map[string]any{"url": "https://hooks.acme.example/tally", "events": []string{"customer.created"}}, &ep)
292		if !ep.Enabled || !strings.HasPrefix(ep.Secret, "whsec_") {
293			t.Fatalf("endpoint = %+v", ep)
294		}
295		for _, bad := range []map[string]any{
296			{"url": "https://does-not-resolve.example/", "events": []string{"*"}},
297			{"url": "not a url", "events": []string{"*"}},
298		} {
299			if r := e.Do("POST", "/v1/webhook-endpoints", e.Acme.Key, bad); r.Code != http.StatusUnprocessableEntity || r.Map(t)["error"] != "invalid_url" {
300				t.Fatalf("%v: %s", bad, r)
301			}
302		}
303		if r := e.Do("POST", "/v1/webhook-endpoints", e.Acme.Key, map[string]any{"url": "https://hooks.acme.example/", "events": []string{"nope"}}); r.Code != http.StatusUnprocessableEntity || r.Map(t)["error"] != "invalid_events" {
304			t.Fatalf("bad events: %s", r)
305		}
306		c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
307		if n, err := e.Webhooks.RunDue(context.Background()); err != nil || n != 1 {
308			t.Fatalf("RunDue = %d, %v", n, err)
309		}
310		if reqs := e.HTTP.Requests(); len(reqs) != 1 || !strings.Contains(string(reqs[0].Body), c.ID) {
311			t.Fatalf("requests = %+v", reqs)
312		}
313		var ds struct{ Items []store.Delivery }
314		e.MustDo(http.StatusOK, "GET", "/v1/webhook-endpoints/"+ep.ID+"/deliveries", e.Acme.Key, nil, &ds)
315		if len(ds.Items) != 1 || ds.Items[0].Status != store.DeliverySucceeded {
316			t.Fatalf("deliveries = %+v", ds)
317		}
318		var evs struct{ Items []store.Event }
319		e.MustDo(http.StatusOK, "GET", "/v1/events?type=customer.created", e.Acme.Key, nil, &evs)
320		if len(evs.Items) != 1 {
321			t.Fatalf("events = %+v", evs)
322		}
323		e.MustDo(http.StatusOK, "PATCH", "/v1/webhook-endpoints/"+ep.ID, e.Acme.Key, map[string]any{"enabled": false}, &ep)
324		if ep.Enabled {
325			t.Fatal("still enabled")
326		}
327		e.CreateCustomer(e.Acme, "John", "john@example.com")
328		if n, _ := e.Webhooks.RunDue(context.Background()); n != 0 {
329			t.Fatalf("a disabled endpoint got %d deliveries", n)
330		}
331		e.MustDo(http.StatusNoContent, "DELETE", "/v1/webhook-endpoints/"+ep.ID, e.Acme.Key, nil, nil)
332		if r := e.Do("GET", "/v1/webhook-endpoints/"+ep.ID, e.Acme.Key, nil); r.Code != http.StatusNotFound {
333			t.Fatalf("deleted endpoint: %s", r)
334		}

285		}
