// SecretOverlap is how long an endpoint's previous secret keeps signing its deliveries after a rotation.
const SecretOverlap = 24 * time.Hour

// defaultTolerance is how far a signature's timestamp may be from the receiver's clock when Verify is given no tolerance.
const defaultTolerance = 5 * time.Minute

// Errors from Verify, checked in this order.
var (
	ErrMalformedHeader    = errors.New("malformed Tally-Signature header")
	ErrNoTimestamp        = errors.New("Tally-Signature header has no timestamp")
	ErrTimestampTolerance = errors.New("Tally-Signature timestamp is outside the tolerance")
	ErrNoSignature        = errors.New("Tally-Signature header has no v1 signature")
	ErrSignatureMismatch  = errors.New("no Tally-Signature v1 signature matches")
)

// SignatureHeader returns the Tally-Signature header of a delivery sent at t: "t=<unix seconds>" and one "v1=<signature>" per
// secret, in the order given (the current secret first). Each signature is Sign of "<t>.<body>".
func SignatureHeader(secrets []string, t time.Time, body []byte) string {
	ts := strconv.FormatInt(t.Unix(), 10)
	signed := append([]byte(ts+"."), body...)
	parts := []string{"t=" + ts}
	for _, secret := range secrets {
		parts = append(parts, "v1="+Sign(secret, signed))
	}
	return strings.Join(parts, ",")
}

// Verify checks a delivery's payload against its Tally-Signature header. It returns nil when the header's timestamp is within
// tolerance of now (0 means 5 minutes) and one of its v1 signatures is the signature of "<t>.<payload>" with one of secrets.
// Otherwise it returns one of the Err errors, matched with errors.Is.
func Verify(payload []byte, header string, secrets []string, tolerance time.Duration, now time.Time) error {
	if tolerance == 0 {
		tolerance = defaultTolerance
	}
	if strings.TrimSpace(header) == "" {
		return fmt.Errorf("%w: the header is empty", ErrMalformedHeader)
	}
	var (
		t       int64
		hasT    bool
		v1s     []string
	)
	for _, pair := range strings.Split(header, ",") {
		k, v, ok := strings.Cut(pair, "=")
		if !ok {
			return fmt.Errorf("%w: %q has no \"=\"", ErrMalformedHeader, strings.TrimSpace(pair))
		}
		k, v = strings.TrimSpace(k), strings.TrimSpace(v)
		switch k {
		case "t":
			n, err := strconv.ParseInt(v, 10, 64)
			if err != nil {
				return fmt.Errorf("%w: t %q is not an integer", ErrMalformedHeader, v)
			}
			if !hasT {
				t, hasT = n, true
			}
		case "v1":
			v1s = append(v1s, v)
		}
	}
	if !hasT {
		return fmt.Errorf("%w", ErrNoTimestamp)
	}
	if d := now.Sub(time.Unix(t, 0)); d < -tolerance || d > tolerance {
		return fmt.Errorf("%w: the timestamp is %v from now", ErrTimestampTolerance, d)
	}
	if len(v1s) == 0 {
		return fmt.Errorf("%w", ErrNoSignature)
	}
	signed := append([]byte(strconv.FormatInt(t, 10)+"."), payload...)
	for _, secret := range secrets {
		want := []byte(Sign(secret, signed))
		for _, v1 := range v1s {
			if hmac.Equal([]byte(v1), want) {
				return nil
			}
		}
	}
	return fmt.Errorf("%w", ErrSignatureMismatch)
}

// activeSecrets returns the secrets that sign a delivery sent at now: the current secret, and the previous one within
// SecretOverlap of a rotation.
func activeSecrets(ep store.WebhookEndpoint, now time.Time) []string {
	secrets := []string{ep.Secret}
	if ep.PreviousSecret != "" && now.Before(ep.PreviousSecretUntil) {
		secrets = append(secrets, ep.PreviousSecret)
	}
	return secrets
}

// RotateSecret gives an endpoint a new signing secret. The previous secret keeps signing its deliveries for SecretOverlap, so
// its receiver can switch over. Rotating again drops the secret before the current one at once.
func (s *Service) RotateSecret(orgID, id string) (store.WebhookEndpoint, error) {
	now := s.clock.Now()
	return s.store.UpdateWebhookEndpoint(orgID, id, func(ep *store.WebhookEndpoint) error {
		ep.PreviousSecret, ep.PreviousSecretUntil = ep.Secret, now.Add(SecretOverlap)
		ep.Secret = NewSecret()
		return nil
	})
}

