// sigOf is the signature a receiver computes for a body delivered at at: Sign of "<t>.<body>".
func sigOf(secret string, at time.Time, body []byte) string {
	return webhooks.Sign(secret, []byte(fmt.Sprintf("%d.%s", at.Unix(), body)))
}

func TestSignatureHeader(t *testing.T) {
	at := time.Unix(1700000000, 0)
	body := []byte(`{"id":"evt_1"}`)
	want := "t=1700000000,v1=" + sigOf("whsec_new", at, body) + ",v1=" + sigOf("whsec_old", at, body)
	if got := webhooks.SignatureHeader([]string{"whsec_new", "whsec_old"}, at, body); got != want {
		t.Fatalf("SignatureHeader = %s, want %s", got, want)
	}
	if got := webhooks.SignatureHeader([]string{"whsec_new"}, at, body); got != "t=1700000000,v1="+sigOf("whsec_new", at, body) {
		t.Fatalf("SignatureHeader with one secret = %s", got)
	}
}

func TestVerify(t *testing.T) {
	at := time.Unix(1700000000, 0)
	body := []byte(`{"id":"evt_1"}`)
	const ts = "t=1700000000"
	sig, old := sigOf("whsec_new", at, body), sigOf("whsec_old", at, body)
	for _, c := range []struct {
		name    string
		payload []byte
		header  string
		secrets []string
		tol     time.Duration
		now     time.Time
		want    error
	}{
		{"current secret", body, ts + ",v1=" + sig, []string{"whsec_new"}, 0, at, nil},
		{"spaces, any order, unknown v0", body, " v1=" + sig + " , v0=abc , " + ts + " ", []string{"whsec_new"}, 0, at, nil},
		{"previous secret in a later v1", body, ts + ",v1=" + sig + ",v1=" + old, []string{"whsec_old"}, 0, at, nil},
		{"any of several secrets", body, ts + ",v1=" + old, []string{"whsec_new", "whsec_old"}, 0, at, nil},
		{"wrong secret", body, ts + ",v1=" + sig, []string{"whsec_other"}, 0, at, webhooks.ErrSignatureMismatch},
		{"no secrets", body, ts + ",v1=" + sig, nil, 0, at, webhooks.ErrSignatureMismatch},
		{"other body", []byte(`{"id":"evt_2"}`), ts + ",v1=" + sig, []string{"whsec_new"}, 0, at, webhooks.ErrSignatureMismatch},
		{"signature for another timestamp", body, "t=1700000001,v1=" + sig, []string{"whsec_new"}, 0, at, webhooks.ErrSignatureMismatch},
		{"default tolerance, edge past", body, ts + ",v1=" + sig, []string{"whsec_new"}, 0, at.Add(5 * time.Minute), nil},
		{"default tolerance, edge future", body, ts + ",v1=" + sig, []string{"whsec_new"}, 0, at.Add(-5 * time.Minute), nil},
		{"default tolerance, too late", body, ts + ",v1=" + sig, []string{"whsec_new"}, 0, at.Add(5*time.Minute + time.Second), webhooks.ErrTimestampTolerance},
		{"default tolerance, too early", body, ts + ",v1=" + sig, []string{"whsec_new"}, 0, at.Add(-5*time.Minute - time.Second), webhooks.ErrTimestampTolerance},
		{"explicit tolerance", body, ts + ",v1=" + sig, []string{"whsec_new"}, 10 * time.Second, at.Add(10 * time.Second), nil},
		{"explicit tolerance, too late", body, ts + ",v1=" + sig, []string{"whsec_new"}, 10 * time.Second, at.Add(11 * time.Second), webhooks.ErrTimestampTolerance},
		{"empty", body, "", []string{"whsec_new"}, 0, at, webhooks.ErrMalformedHeader},
		{"blank", body, "  ", []string{"whsec_new"}, 0, at, webhooks.ErrMalformedHeader},
		{"pair without =", body, ts + ",v1=" + sig + ",v1", []string{"whsec_new"}, 0, at, webhooks.ErrMalformedHeader},
		{"t is not an integer", body, "t=soon,v1=" + sig, []string{"whsec_new"}, 0, at, webhooks.ErrMalformedHeader},
		{"t is empty", body, "t=,v1=" + sig, []string{"whsec_new"}, 0, at, webhooks.ErrMalformedHeader},
		{"malformed before no timestamp", body, "v0=x,v1", []string{"whsec_new"}, 0, at, webhooks.ErrMalformedHeader},
		{"no timestamp", body, "v1=" + sig, []string{"whsec_new"}, 0, at, webhooks.ErrNoTimestamp},
		{"no signature", body, ts, []string{"whsec_new"}, 0, at, webhooks.ErrNoSignature},
		{"tolerance before no signature", body, ts, []string{"whsec_new"}, 0, at.Add(time.Hour), webhooks.ErrTimestampTolerance},
	} {
		err := webhooks.Verify(c.payload, c.header, c.secrets, c.tol, c.now)
		if !errors.Is(err, c.want) {
			t.Errorf("%s: Verify = %v, want %v", c.name, err, c.want)
		}
	}
}

func TestRotateSecret(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	ep, _ := e.Store.CreateWebhookEndpoint(store.WebhookEndpoint{OrgID: e.Acme.ID, URL: "https://hooks.acme.example/all", Events: []string{"*"}, Secret: "whsec_1", Enabled: true}, e.Clock.Now())
	// send delivers one event to the endpoint and returns the request's signature header and body.
	send := func() (string, []byte) {
		t.Helper()
		if err := e.Webhooks.Publish(ctx, e.Acme.ID, "customer.created", map[string]string{"id": "cus_1"}); err != nil {
			t.Fatal(err)
		}
		if n, err := e.Webhooks.RunDue(ctx); err != nil || n != 1 {
			t.Fatalf("RunDue = %d, %v", n, err)
		}
		reqs := e.HTTP.Requests()
		last := reqs[len(reqs)-1]
		return last.Header.Get("Tally-Signature"), last.Body
	}
	// check wants the header of a delivery sent now to carry one v1 entry per secret, current first, and to verify.
	check := func(header string, body []byte, secrets ...string) {
		t.Helper()
		now := e.Clock.Now()
		if want := webhooks.SignatureHeader(secrets, now, body); header != want {
			t.Fatalf("header = %s, want %s", header, want)
		}
		if err := webhooks.Verify(body, header, secrets, 0, now); err != nil {
			t.Fatalf("Verify: %v", err)
		}
	}

	h, b := send()
	check(h, b, "whsec_1")

	rot, err := e.Webhooks.RotateSecret(e.Acme.ID, ep.ID)
	if err != nil {
		t.Fatal(err)
	}
	second := rot.Secret
	if !strings.HasPrefix(second, "whsec_") || second == "whsec_1" || rot.PreviousSecret != "whsec_1" {
		t.Fatalf("rotated endpoint = %+v", rot)
	}
	h, b = send()
	check(h, b, second, "whsec_1")

	// Just before the overlap ends, the previous secret still signs.
	e.Clock.Advance(webhooks.SecretOverlap - time.Second)
	h, b = send()
	check(h, b, second, "whsec_1")
	e.Clock.Advance(time.Second)
	h, b = send()
	check(h, b, second)
	if err := webhooks.Verify(b, h, []string{"whsec_1"}, 0, e.Clock.Now()); !errors.Is(err, webhooks.ErrSignatureMismatch) {
		t.Fatalf("the expired secret still verifies: %v", err)
	}

	// Rotating again keeps the current secret and the one before it; the oldest is dropped at once.
	rot, _ = e.Webhooks.RotateSecret(e.Acme.ID, ep.ID)
	third := rot.Secret
	h, b = send()
	check(h, b, third, second)
	e.Clock.Advance(time.Hour)
	rot, _ = e.Webhooks.RotateSecret(e.Acme.ID, ep.ID)
	fourth := rot.Secret
	h, b = send()
	check(h, b, fourth, third)
	if err := webhooks.Verify(b, h, []string{second}, 0, e.Clock.Now()); !errors.Is(err, webhooks.ErrSignatureMismatch) {
		t.Fatalf("a secret dropped by a rotation still verifies: %v", err)
	}
}

